  private eligibleStoredMappings():AnkiMappingPreset[]{return eligibleAnkiMappings(this.store.data()?.ankiMappings??[],this.sourceMode==='update'?'update':this.sourceMode==='repair'||this.sourceMode==='mapping'?'repair':'import');}
